/**
 * Reads parity_fixture.json (generated by
 * stock_eval/tools/generate_parity_fixture.py) and verifies that
 * scoring.js reproduces the same interpolation, calibration, and
 * trajectory multiplier values Python computed.
 *
 * Usage:
 *   python -m stock_eval.tools.generate_parity_fixture   # from the Python repo
 *   cp parity_fixture.json <this js repo>/
 *   node parity_check.js
 *
 * Exits non-zero if any case exceeds the tolerance -- wire this into CI
 * so a change to either side's math gets caught immediately, not
 * discovered later as a live scoring discrepancy.
 */

'use strict';

const fs = require('fs');
const path = require('path');
const { interpolateLevelScore, trajectoryMultiplier } = require('./src/scoring');
const { computeAllIndicators } = require('./src/indicators');

const TOLERANCE = 1e-9;
// Indicator computation involves many chained floating-point operations
// (rolling windows, recursive EWM) across up to 200 rows, so a slightly
// looser tolerance than the scoring-math checks is appropriate here --
// still tight enough to catch a genuine formula/convention mismatch.
const INDICATOR_TOLERANCE = 1e-6;

function loadFixture() {
  const fixturePath = path.join(__dirname, 'parity_fixture.json');
  if (!fs.existsSync(fixturePath)) {
    console.error(
      `Fixture not found at ${fixturePath}.\n` +
      `Generate it first: python -m stock_eval.tools.generate_parity_fixture\n` +
      `then copy parity_fixture.json into this directory.`
    );
    process.exit(1);
  }
  return JSON.parse(fs.readFileSync(fixturePath, 'utf8'));
}

function checkClose(label, actual, expected, tolerance = TOLERANCE) {
  const diff = Math.abs(actual - expected);
  const pass = diff <= tolerance;
  const status = pass ? 'PASS' : 'FAIL';
  console.log(
    `[${status}] ${label}: actual=${actual.toFixed(10)} expected=${expected.toFixed(10)} diff=${diff.toExponential(3)}`
  );
  return pass;
}

/**
 * Compares a computed indicator series against the expected series
 * element-by-element. Both null (pandas NaN) => match. One null, one
 * number => mismatch (means the two sides disagree about *where* the
 * indicator becomes available, e.g. a min_periods discrepancy). Both
 * numbers => must be within tolerance.
 */
function checkIndicatorSeries(name, actual, expected) {
  if (actual.length !== expected.length) {
    console.log(`[FAIL] ${name}: length mismatch (actual=${actual.length}, expected=${expected.length})`);
    return false;
  }

  let pass = true;
  let firstMismatchIdx = null;
  let maxDiff = 0;

  for (let i = 0; i < actual.length; i++) {
    const a = actual[i];
    const e = expected[i];
    const aIsNull = a === null || a === undefined || Number.isNaN(a);
    const eIsNull = e === null || e === undefined;

    if (aIsNull !== eIsNull) {
      pass = false;
      if (firstMismatchIdx === null) firstMismatchIdx = i;
      continue;
    }
    if (aIsNull && eIsNull) continue; // both NaN/null -> agree

    const diff = Math.abs(a - e);
    maxDiff = Math.max(maxDiff, diff);
    if (diff > INDICATOR_TOLERANCE) {
      pass = false;
      if (firstMismatchIdx === null) firstMismatchIdx = i;
    }
  }

  const status = pass ? 'PASS' : 'FAIL';
  const detail = pass
    ? `max_diff=${maxDiff.toExponential(3)}`
    : `first mismatch at index ${firstMismatchIdx} (actual=${actual[firstMismatchIdx]}, expected=${expected[firstMismatchIdx]})`;
  console.log(`[${status}] ${name}: ${detail}`);
  return pass;
}

function main() {
  const fixture = loadFixture();
  let allPassed = true;

  console.log('--- Indicator computation parity (OHLCV -> indicator series) ---');
  const actualIndicators = computeAllIndicators(fixture.ohlcv);
  for (const [name, expectedSeries] of Object.entries(fixture.expected_indicators)) {
    const pass = checkIndicatorSeries(name, actualIndicators[name], expectedSeries);
    allPassed = allPassed && pass;
  }

  console.log('\n--- Level score / interpolation parity ---');
  for (const c of fixture.level_cases) {
    const actual = interpolateLevelScore(fixture.lookup_table, c.value);
    const pass = checkClose(`value=${c.value}`, actual, c.expected_level_score);
    allPassed = allPassed && pass;
  }

  console.log('\n--- Trajectory multiplier parity ---');
  for (const c of fixture.trajectory_cases) {
    const actual = trajectoryMultiplier(c.slope, c.gradient);
    const pass = checkClose(
      `slope=${c.slope}, gradient=${c.gradient}`,
      actual,
      c.expected_multiplier
    );
    allPassed = allPassed && pass;
  }

  console.log(`\n${allPassed ? 'ALL CASES PASSED' : 'SOME CASES FAILED'} -- ` +
    `Python/JS formula parity ${allPassed ? 'confirmed' : 'BROKEN, do not deploy'}.`);

  process.exit(allPassed ? 0 : 1);
}

main();
